// The mascot's art and motion: the brand mark itself — the 4A line chick (tuft of three bumps, dot eyes, diamond beak,
// wing nubs, sound arcs; Icons/MascotGeometry.swift, generated by assets/brand/chick.swift) — in colour: a warm yellow
// body under the icon's #17140F line, a coral beak. Pure CoreGraphics, vector: crisp at any size.
//
//   MascotArt.pose(.happy, at: 0.4)                        a clip at a moment: where every part is (MascotPose)
//   MascotArt.draw(ctx, in: rect, pose: p, style: s)       paints that pose, square, into any context (y up)
//
// Each clip is a function of time, not frames: Icons/Mascot.swift samples it on its layers' timer; docs and tests
// sample it at any rate (`mascotframes`). The chick is posed part by part about its foot: a hop with squash and stretch,
// a tilt, the wings flapping (drawn whole behind the body, so the body hides all but the nub, as on the icon), the eyes
// blinking, looking or smiling (^ ^), the beak opening, the sound arcs pulsing; props: the egg it hatches from (cracks,
// the cap flies off and shrinks away, it hops out of the cup, which sinks), thought dots, sparkles, the bug it pounces
// on. Shell pieces stay opaque (a fading shell reads as a grey ghost). On a dark backdrop the chick and egg get a thin
// white rim (MascotStyle.rim), the logo's sticker edge made thinner, so the black line reads on the island's black.
//
//   idle       breathes, blinks, glances aside (loop)
//   listening  head tilted, the sound arcs pulse outward, inner then outer (loop; the menu-bar glyph does the same)
//   thinking   eyes up, three thought dots rise where the arcs were (loop)
//   wobble     the egg alone, rocking: captures being organized (loop)
//   hatching   the egg rocks, cracks, the cap flies off, the chick pops up, hops out, its arcs appear (once)
//   happy      two hops, wings up, ^ ^ eyes, the beak open, the arcs ring out, sparkles (once)
//   peck       spots a bug, pounces on it; the bug goes in a sparkle; a happy hop back (once)
//
// Each clip has a still moment that says the same thing without motion (Reduce Motion, notification pictures).
import CoreGraphics
import Foundation

/// One drawing of the 4A chick, in chick.swift's hero space (y down). Values: MascotGeometry.swift (generated).
struct MascotGeometry {
    let cx: CGFloat, foot: CGFloat, line: CGFloat
    let outline: CGPath
    let wing: (dx: CGFloat, cy: CGFloat, rx: CGFloat, ry: CGFloat, deg: CGFloat)
    let eye: (dx: CGFloat, cy: CGFloat, r: CGFloat)
    let glint: (dx: CGFloat, dy: CGFloat, r: CGFloat)
    let beak: (cy: CGFloat, w: CGFloat, up: CGFloat, down: CGFloat)
    let slit: Bool, filledBeak: Bool
    let arcCentre: CGPoint
    let arcs: [(r: CGFloat, from: CGFloat, to: CGFloat)]

    static func path(_ build: (CGMutablePath) -> Void) -> CGPath {
        let p = CGMutablePath()
        build(p)
        return p
    }
}

/// The mascot's colours (sRGB hex; MascotGeometry.swift, from chick.swift).
enum MascotPalette {}

/// Where every part of the chick is at one moment. Lengths in hero units (the stage is 1320 wide), angles in radians.
struct MascotPose {
    var chick = true
    var x: CGFloat = 0                 // sideways (the peck's pounce)
    var lift: CGFloat = 0              // up from the ground (hops)
    var squash: CGFloat = 0            // + wider and shorter, − taller (about the foot)
    var tilt: CGFloat = 0              // about the foot; + leans right
    var scale: CGFloat = 1
    var wing: CGFloat = 0              // both wings up / out (flap)
    var blink: CGFloat = 0             // 0 open … 1 shut
    var happy = false                  // ^ ^ eyes
    var look = CGPoint.zero            // the eyes' offset, in eye radii
    var beak: CGFloat = 0              // 0 shut … 1 open
    var arcs: [CGFloat] = [1, 1]       // each sound arc's opacity, inner first
    var arcGrow: [CGFloat] = [0, 0]    // each arc's extra radius, as a fraction
    var dots: [CGFloat] = []           // thought dots' opacity
    // the egg
    var egg = false                    // the whole egg (the chick inside, not drawn)
    var eggTilt: CGFloat = 0
    var crack: CGFloat = 0             // how much of the crack is drawn
    var cup: CGFloat = 0               // the bottom shell's size (0 gone … 1 whole; opaque, it shrinks into the ground)
    var inCup = false                  // the chick is still in the cup: nothing of it shows below the shell
    var cupDrop: CGFloat = 0
    /// the flying top shell: shown (0/1, it stays opaque), where it has flown, its turn, its size (it shrinks away)
    var cap: (alpha: CGFloat, dx: CGFloat, dy: CGFloat, turn: CGFloat, size: CGFloat) = (0, 0, 0, 0, 1)
    // the bug and the sparkles
    var bug: CGFloat = 0               // opacity
    var bugSquish: CGFloat = 0
    var sparkles: [(at: CGPoint, size: CGFloat, alpha: CGFloat, warm: Bool)] = []
}

/// How a mascot is drawn besides its pose: what it sits on and how small it is.
struct MascotStyle {
    /// Sits on a dark backdrop (the island, dark mode): the free marks (arcs, dots) turn light, the ground shadow goes
    /// (and `forSize` turns on `rim`).
    var dark = false
    /// 32 pt and less: the small icon's drawing (heavier line, one arc, filled beak, no glints).
    var small = false
    /// The thinnest line, in the context's units (the hero line scales down with the size; this keeps it visible).
    var minLine: CGFloat = 0
    /// A white sticker edge round the art, as on the logo: for pictures shown on any backdrop (notifications).
    var sticker = false
    /// A thin light edge round the chick and the egg on a dark backdrop, so the black line (the logo's tuft, the wing
    /// nubs, the shell) still reads on the island's black; the free marks are light already and get none.
    var rim = false

    static func forSize(_ points: CGFloat, dark: Bool, scale: CGFloat = 2) -> MascotStyle {
        MascotStyle(dark: dark, small: points <= 32, minLine: 1.3 * scale, rim: dark)
    }
}

enum MascotArt {
    /// The square the mascot is drawn in, in hero space: the art (wings to arcs) is 87 % of its width, centred; the foot
    /// sits 7 % above its bottom; the room above is for hops, the flying egg cap and thought dots.
    static let stage = CGRect(x: -28, y: -128, width: 1320, height: 1320)
    /// How far past the stage a moment may reach, as a fraction of its side (a landing squash with the rim, the egg cap
    /// flying up, the pounce): MascotLayer draws this much extra room, and `check` holds every clip inside it.
    static let bleed: CGFloat = 0.04

    struct Timing {
        let duration: Double
        let loop: Bool
        /// The moment that says the clip without motion (Reduce Motion, a notification's picture).
        let still: Double
    }

    static func timing(_ c: MascotClip) -> Timing {
        switch c {
        case .idle: return Timing(duration: 4.2, loop: true, still: 0)
        case .listening: return Timing(duration: 2.4, loop: true, still: 0.9)
        case .thinking: return Timing(duration: 2.4, loop: true, still: 1.2)
        case .wobble: return Timing(duration: 1.6, loop: true, still: 0)
        case .hatching: return Timing(duration: 2.1, loop: false, still: 2.1)
        case .happy: return Timing(duration: 1.9, loop: false, still: 1.25)
        case .peck: return Timing(duration: 2.9, loop: false, still: 1.45)
        }
    }

    // MARK: - the clips

    static func pose(_ c: MascotClip, at time: Double) -> MascotPose {
        let tm = timing(c)
        let t = tm.loop ? time.truncatingRemainder(dividingBy: tm.duration) : min(max(0, time), tm.duration)
        var p = MascotPose()
        switch c {
        case .idle:
            p.squash = 0.012 * CGFloat(sin(2 * .pi * t / 2.1))
            p.blink = blink(t, 1.0) + blink(t, 3.05) + blink(t, 3.3)
            let glance = smooth(span(t, 1.5, 1.75)) * (1 - smooth(span(t, 2.45, 2.7)))
            p.look = CGPoint(x: 0.24 * glance, y: 0.04 * glance)
            p.wing = 0.03 * CGFloat(sin(2 * .pi * t / 2.1))

        case .listening:
            // the head tilts and holds; the arcs pulse outward twice a loop, the outer one a beat behind
            let on = smooth(span(t, 0, 0.45)) * (1 - smooth(span(t, 1.75, 2.25)))
            p.tilt = -0.1 * on
            p.lift = 6 * CGFloat(sin(2 * .pi * t / 1.2))
            p.look = CGPoint(x: 0.14 * on, y: -0.08 * on)
            for i in 0..<2 {
                let ph = (t - 0.16 * Double(i)).truncatingRemainder(dividingBy: 1.2) / 1.2
                let k = CGFloat(ph < 0 ? 0 : sin(.pi * min(1, ph / 0.7)))
                p.arcs[i] = 0.28 + 0.72 * k
                p.arcGrow[i] = 0.07 * k
            }
            p.blink = blink(t, 2.05)

        case .thinking:
            p.arcs = [0, 0]
            p.look = CGPoint(x: 0.26, y: -0.36)
            p.tilt = 0.05 * CGFloat(sin(2 * .pi * t / 2.4))
            p.dots = (0..<3).map { i in
                let a = 0.15 + 0.28 * Double(i)
                return smooth(span(t, a, a + 0.22)) * (1 - smooth(span(t, 1.85, 2.25)))
            }
            p.blink = blink(t, 1.55)

        case .wobble:
            p.chick = false
            p.egg = true
            let k = span(t, 0, 0.75)
            p.eggTilt = k < 1 ? 0.15 * CGFloat(sin(2 * .pi * 3 * Double(k))) * (1 - k) : 0

        case .hatching:
            if t < 0.95 {
                p.chick = false
                p.egg = true
                let a = span(t, 0, 0.5), b = span(t, 0.72, 0.95)
                p.eggTilt = (a < 1 ? 0.13 * CGFloat(sin(2 * .pi * 2 * Double(a))) * (1 - a) : 0)
                    + 0.08 * CGFloat(sin(2 * .pi * 3 * Double(b))) * (b > 0 && b < 1 ? 1 : 0)
                p.crack = smooth(span(t, 0.42, 0.72))
            } else {
                // the cap flies off up and to the right, turning; the chick pops up in the cup, then hops out of it
                let f = span(t, 0.95, 1.5)
                // it stays a solid piece of shell and shrinks away (a fade showed the chick through a grey ghost)
                let gone = smooth(span(t, 1.18, 1.5))
                p.cap = (alpha: gone < 1 ? 1 : 0, dx: 380 * f, dy: -620 * f + 400 * f * f, turn: 1.2 * f, size: 1 - gone)
                let rise = Ease.outBack(span(t, 0.95, 1.3), 1.3)
                p.inCup = t < 1.5
                p.cup = 1 - smooth(span(t, 1.5, 1.66))
                p.cupDrop = 20 * span(t, 1.5, 1.66)
                p.scale = 0.82 + 0.18 * smooth(span(t, 1.5, 1.8))
                let h = hop(t, at: 1.5, air: 0.3, height: 150)
                p.lift = h.lift - 330 * (1 - rise)
                p.squash = h.squash
                p.blink = 1 - span(t, 1.22, 1.36)
                p.arcs = [span(t, 1.3, 1.45), span(t, 1.38, 1.53)]
                p.arcGrow = p.arcs.map { 0.12 * (1 - $0) }
                p.wing = 0.4 * bell(t, 1.5, 1.85)
            }

        case .happy:
            let h1 = hop(t, at: 0.12, air: 0.38, height: 155), h2 = hop(t, at: 0.66, air: 0.3, height: 110)
            p.lift = h1.lift + h2.lift
            p.squash = h1.squash + h2.squash
            let air = bell(t, 0.08, 0.56) + bell(t, 0.62, 1.0)
            p.wing = 0.5 * air + 0.12 * air * CGFloat(sin(2 * .pi * 9 * t))
            p.happy = t > 0.06 && t < 1.5
            p.blink = bell(t, 1.42, 1.6)
            p.beak = 0.85 * bell(t, 0.14, 0.52) + 0.55 * bell(t, 0.66, 0.96)
            p.arcGrow = [0.12 * bell(t, 0.18, 0.6) + 0.08 * bell(t, 0.7, 1.05), 0.14 * bell(t, 0.24, 0.66) + 0.1 * bell(t, 0.76, 1.1)]
            // sparkles to the left and above, clear of the head and the arcs (on the right)
            p.sparkles = burst(t, from: 0.24, around: CGPoint(x: 626, y: 600), radius: 540, angles: [-168, -128])
                + burst(t, from: 0.76, around: CGPoint(x: 626, y: 560), radius: 560, angles: [-148, -108])

        case .peck:
            // spots the bug, pounces on it (the bug goes in a sparkle), a happy hop back to the middle; the travel keeps
            // the whole chick (wings up, rim, ringing arcs) inside the stage at both ends
            let go = hop(t, at: 0.66, air: 0.4, height: 240), back = hop(t, at: 2.0, air: 0.34, height: 130)
            p.x = -145 + 300 * smooth(span(t, 0.66, 1.06)) - 155 * smooth(span(t, 2.0, 2.34))
            p.lift = go.lift + back.lift
            p.squash = go.squash + back.squash
            p.scale = 0.78 + 0.22 * smooth(span(t, 2.0, 2.34))
            let seen = smooth(span(t, 0.1, 0.3)) * (1 - span(t, 1.0, 1.06))
            p.look = CGPoint(x: 0.38 * seen, y: 0.3 * seen)
            p.tilt = 0.08 * seen * (1 - span(t, 0.56, 0.66))
            p.blink = blink(t, 0.36) + bell(t, 1.86, 2.0)
            p.happy = t > 1.08 && t < 1.92
            p.wing = 0.45 * bell(t, 1.06, 1.5) + 0.35 * bell(t, 1.98, 2.4)
            p.beak = 0.6 * bell(t, 1.06, 1.4)
            p.arcGrow = [0.12 * bell(t, 1.1, 1.5), 0.14 * bell(t, 1.16, 1.56)]
            p.bug = t < 1.06 ? 1 : 0
            p.bugSquish = 0.25 * bell(t, 0.98, 1.06)
            p.sparkles = burst(t, from: 1.06, around: CGPoint(x: 781, y: 640), radius: 470, angles: [-168, -128, -62])
        }
        p.blink = min(1, p.blink)
        return p
    }

    /// What should hold of every clip (the `mascotcheck` self-test): one-shots end on the chick at rest, where `idle`
    /// (onboarding's `then`) begins, so nothing jumps; loops join up; every still moment draws something;
    /// shell pieces are never half-transparent; on black the chick's edge is the light rim;
    /// nothing reaches past the stage's bleed. Problems, or [].
    static func check() -> [String] {
        var bad: [String] = []
        func near(_ a: CGFloat, _ b: CGFloat, _ eps: CGFloat = 0.01) -> Bool { abs(a - b) <= eps }
        for c in MascotClip.allCases {
            let t = timing(c)
            if t.loop {
                let a = pose(c, at: 0), b = pose(c, at: t.duration - 1e-6)
                if !(near(a.lift, b.lift, 0.5) && near(a.tilt, b.tilt) && near(a.squash, b.squash) && near(a.eggTilt, b.eggTilt)) {
                    bad.append("\(c.rawValue): the loop jumps")
                }
            } else {
                let e = pose(c, at: t.duration)
                if !(e.chick && !e.egg && e.cup == 0 && e.cap.alpha == 0 && e.bug == 0 && e.sparkles.isEmpty && !e.happy
                     && near(e.lift, 0, 0.5) && near(e.squash, 0) && near(e.scale, 1) && near(e.x, 0, 0.5) && e.blink < 0.05) {
                    bad.append("\(c.rawValue): does not end at rest")
                }
            }
            if t.still < 0 || t.still > t.duration { bad.append("\(c.rawValue): still moment outside the clip") }
            // shell pieces are solid or gone, never a half-transparent ghost
            for i in 0...60 where ![0, 1].contains(pose(c, at: t.duration * Double(i) / 60).cap.alpha) {
                bad.append("\(c.rawValue): the cap is half-transparent"); break
            }
        }
        // nothing is cut off: no paint on the border of the stage plus its bleed, at any moment of any clip (dark: with
        // the rim)
        for c in MascotClip.allCases {
            let side: CGFloat = 112, pad = side * bleed, px = Int(side + 2 * pad), n = 48
            guard let ctx = CGContext(data: nil, width: px, height: px, bitsPerComponent: 8, bytesPerRow: px * 4,
                                      space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                      bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue), let data = ctx.data else { continue }
            let bytes = data.bindMemory(to: UInt8.self, capacity: px * px * 4)
            let d = timing(c).duration
            outer: for i in 0...n {
                ctx.clear(CGRect(x: 0, y: 0, width: px, height: px))
                draw(ctx, in: CGRect(x: pad, y: pad, width: side, height: side), pose: pose(c, at: d * Double(i) / Double(n)),
                     style: .forSize(56, dark: true))
                for k in 0..<px where [(0, k), (px - 1, k), (k, 0), (k, px - 1)].contains(where: { bytes[($0.1 * px + $0.0) * 4 + 3] > 8 }) {
                    bad.append("\(c.rawValue): reaches past the stage's bleed"); break outer
                }
            }
        }
        // on black the chick's outer edge is the light rim, not its black line lost in the backdrop (ear and toast sizes)
        for points: CGFloat in [24, 56] {
            let px = Int(points * 2)
            guard let ctx = CGContext(data: nil, width: px, height: px, bitsPerComponent: 8, bytesPerRow: px * 4,
                                      space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                      bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue), let data = ctx.data else { continue }
            ctx.setFillColor(CGColor(srgbRed: 0, green: 0, blue: 0, alpha: 1))
            ctx.fill(CGRect(x: 0, y: 0, width: px, height: px))
            draw(ctx, in: CGRect(x: 0, y: 0, width: px, height: px), pose: pose(.idle, at: 0), style: .forSize(points, dark: true))
            let bytes = data.bindMemory(to: UInt8.self, capacity: px * px * 4)
            // the first lit pixel from the left, along the row through the body's middle (the wing nub's side)
            let row = px / 2
            let rgb = (0..<px).map { x in (0..<3).map { Int(bytes[(row * px + x) * 4 + $0]) } }
            // past the anti-aliased first pixel: the whitest of the next few (its weakest channel, so the yellow
            // wing does not pass for the rim), before the black line begins
            let edge = rgb.firstIndex { $0.max()! > 40 }.map { i in rgb[i..<min(px, i + 3)].map { $0.min()! }.max()! }
            if (edge ?? 0) < 200 { bad.append("on dark at \(Int(points)) pt the chick's edge is not light") }
        }
        return bad
    }

    /// Where the bug sits in the peck (hero space): on the ground, right of the chick.
    static let bugAt = CGPoint(x: 821, y: 1030)

    // MARK: - timing helpers

    /// 0 before `a`, 1 after `b`, linear between.
    private static func span(_ t: Double, _ a: Double, _ b: Double) -> CGFloat { CGFloat(min(1, max(0, (t - a) / (b - a)))) }
    private static func smooth(_ p: CGFloat) -> CGFloat { p * p * (3 - 2 * p) }
    /// A half sine from `a` to `b`, 0 outside.
    private static func bell(_ t: Double, _ a: Double, _ b: Double) -> CGFloat {
        let p = span(t, a, b)
        return p <= 0 || p >= 1 ? 0 : CGFloat(sin(.pi * Double(p)))
    }
    private static func blink(_ t: Double, _ at: Double) -> CGFloat { bell(t, at, at + 0.15) }

    /// One hop taking off at `a`: a squash before it, `air` seconds up to `height` and down (stretched while rising),
    /// a squash on landing.
    private static func hop(_ t: Double, at a: Double, air: Double, height: CGFloat) -> (lift: CGFloat, squash: CGFloat) {
        let pre = 0.1, post = 0.14
        if t < a - pre || t > a + air + post { return (0, 0) }
        if t < a { return (0, 0.13 * smooth(span(t, a - pre, a))) }
        if t <= a + air {
            let p = CGFloat((t - a) / air)
            return (height * 4 * p * (1 - p), -0.09 * (1 - p) * (1 - p) + 0.02 * p)
        }
        let p = span(t, a + air, a + air + post)
        return (0, 0.15 * CGFloat(sin(.pi * Double(p))) * (1 - 0.4 * p))
    }

    /// Sparkles popping out from `c` at `angles` (degrees, y down: −90 = up) from `a`, drifting out and up, fading
    /// over 0.6 s. Kept clear of the head and the arcs by the callers' angles.
    private static func burst(_ t: Double, from a: Double, around c: CGPoint, radius: CGFloat,
                              angles: [Double]) -> [(at: CGPoint, size: CGFloat, alpha: CGFloat, warm: Bool)] {
        let p = span(t, a, a + 0.6)
        guard p > 0, p < 1 else { return [] }
        return angles.enumerated().map { i, deg in
            let ang = deg * .pi / 180
            let r = radius * (0.8 + 0.2 * Ease.outCubic(p))
            let at = CGPoint(x: c.x + r * CGFloat(cos(ang)), y: c.y + r * CGFloat(sin(ang)) - 50 * p)
            let size = (i % 2 == 0 ? 92 : 68) * (p < 0.25 ? Ease.outBack(p / 0.25) : 1 - 0.5 * (p - 0.25))
            return (at, size, 1 - smooth(span(Double(p), 0.55, 1)), i % 2 == 0)
        }
    }

    // MARK: - drawing

    /// Paints `pose` into `rect` (square; fitted and centred) of a y-up context (`flipped`: a y-down one).
    static func draw(_ ctx: CGContext, in rect: CGRect, pose: MascotPose, style: MascotStyle, flipped: Bool = false) {
        let g = style.small ? MascotGeometry.small : MascotGeometry.master
        let side = min(rect.width, rect.height)
        let k = side / stage.width
        ctx.saveGState()
        // hero space (y down) onto the rect
        if flipped {
            ctx.translateBy(x: rect.midX - side / 2, y: rect.midY - side / 2)
            ctx.scaleBy(x: k, y: k)
        } else {
            ctx.translateBy(x: rect.midX - side / 2, y: rect.midY + side / 2)
            ctx.scaleBy(x: k, y: -k)
        }
        ctx.translateBy(x: -stage.minX, y: -stage.minY)
        ctx.setLineCap(.round)
        ctx.setLineJoin(.round)
        let ink = Painter(g: g, style: style, line: max(g.line, style.minLine / k))
        if style.sticker || style.rim {
            // the logo's sticker edge (or the thinner rim on dark): the same drawing in white, a wide line, under everything
            ink.sticker = true
            ink.paint(ctx, pose)
            ink.sticker = false
        }
        ink.paint(ctx, pose)
        ctx.restoreGState()
    }

    /// Paints the parts in order. `sticker`: the edge pass, everything in white with a wide line (under the art); with
    /// only `style.rim` the line is thinner and the free marks (arcs, sparkles) are left out.
    private final class Painter {
        let g: MascotGeometry
        let style: MascotStyle
        let line: CGFloat
        var sticker = false

        init(g: MascotGeometry, style: MascotStyle, line: CGFloat) { self.g = g; self.style = style; self.line = line }

        func color(_ hex: UInt32, _ a: CGFloat = 1) -> CGColor {
            if sticker { return CGColor(srgbRed: 1, green: 1, blue: 1, alpha: a > 0 ? 1 : 0) }
            return CGColor(srgbRed: CGFloat(hex >> 16 & 0xff) / 255, green: CGFloat(hex >> 8 & 0xff) / 255,
                           blue: CGFloat(hex & 0xff) / 255, alpha: a)
        }
        var lineColor: CGColor { color(MascotPalette.line) }
        /// arcs, dots: on a dark backdrop the line colour would vanish
        func free(_ a: CGFloat) -> CGColor { color(style.dark ? MascotPalette.inkOnDark : MascotPalette.line, a) }
        // the rim on dark: 2.2 lines wide at ear and toast sizes (where a thinner one is lost), 1.8 above them — wider
        // read as a sticker cut-out round the chick, heavier than its own line
        var width: CGFloat { sticker ? line * (style.sticker ? 3.4 : style.small ? 2.2 : 1.8) : line }
        /// the rim's pass: only the chick and the egg get an edge
        var rimOnly: Bool { sticker && !style.sticker }

        func paint(_ ctx: CGContext, _ p: MascotPose) {
            if p.bug > 0 && !sticker { bug(ctx, p) }
            // the egg: over the chick while it is inside, behind it once it has hopped out (the cup fading away)
            let eggFirst = p.chick && !p.inCup
            if eggFirst && (p.cup > 0 || p.cap.alpha > 0) { egg(ctx, p) }
            if p.chick {
                if !style.dark && !sticker && !p.inCup { shadow(ctx, p) }
                ctx.saveGState()
                if p.inCup {
                    // in the cup: only what is above the crack or inside the shell shows (the cup is drawn over it)
                    ctx.addPath(MascotArt.egg.room)
                    ctx.clip()
                }
                place(ctx, p)
                chick(ctx, p)
                ctx.restoreGState()
            }
            if !eggFirst && (p.egg || p.cup > 0 || p.cap.alpha > 0) { egg(ctx, p) }
            if !rimOnly { for s in p.sparkles where s.alpha > 0 { sparkle(ctx, s.at, s.size, s.alpha, warm: s.warm) } }
        }

        /// The chick's transform: about its foot, moved, lifted, tilted, squashed.
        func place(_ ctx: CGContext, _ p: MascotPose) {
            ctx.translateBy(x: g.cx + p.x, y: g.foot - p.lift)
            ctx.rotate(by: p.tilt)
            ctx.scaleBy(x: p.scale * (1 + p.squash), y: p.scale * (1 - p.squash))
            ctx.translateBy(x: -g.cx, y: -g.foot)
        }

        /// A soft ground shadow that shrinks as the chick lifts (light backdrops only).
        func shadow(_ ctx: CGContext, _ p: MascotPose) {
            let w = 620 * p.scale * (1 + p.squash) * (1 - min(0.5, p.lift / 600))
            let a = 0.1 * (1 - min(0.6, p.lift / 500)) * (p.egg ? 0 : 1)
            ctx.setFillColor(color(MascotPalette.line, a))
            ctx.fillEllipse(in: CGRect(x: g.cx + p.x - w / 2, y: g.foot - 22, width: w, height: 44))
        }

        func chick(_ ctx: CGContext, _ p: MascotPose) {
            let w = width
            ctx.setLineWidth(w)
            // the wings, whole, behind the body (the body hides all but the nub, as on the icon)
            for side: CGFloat in [1, -1] {
                let loop = wingLoop(side, flap: p.wing)
                ctx.addPath(loop); ctx.setFillColor(color(MascotPalette.wing)); ctx.fillPath()
                ctx.addPath(loop); ctx.setStrokeColor(lineColor); ctx.strokePath()
            }
            // the body: yellow, a soft shade low down, the line
            ctx.addPath(g.outline); ctx.setFillColor(color(MascotPalette.body)); ctx.fillPath()
            if !sticker {
                ctx.saveGState()
                ctx.addPath(g.outline); ctx.clip()
                let cs = CGColorSpace(name: CGColorSpace.sRGB)!
                if let grad = CGGradient(colorsSpace: cs, colors: [color(MascotPalette.shade, 0), color(MascotPalette.shade, 0.55)] as CFArray,
                                         locations: [0, 1]) {
                    ctx.drawRadialGradient(grad, startCenter: CGPoint(x: g.cx - 120, y: 560), startRadius: 300,
                                           endCenter: CGPoint(x: g.cx - 60, y: 640), endRadius: 640, options: [.drawsAfterEndLocation])
                }
                // the cheeks (not small: they'd smudge the face)
                let e = g.eye
                ctx.setFillColor(color(MascotPalette.blush, style.small ? 0 : 0.3))
                for s: CGFloat in [-1, 1] {
                    ctx.fillEllipse(in: CGRect(x: g.cx + s * (e.dx + e.r * 0.95) - e.r * 0.9, y: e.cy + e.r * 1.25 - e.r * 0.5,
                                               width: e.r * 1.8, height: e.r))
                }
                ctx.restoreGState()
            }
            ctx.addPath(g.outline); ctx.setStrokeColor(lineColor); ctx.strokePath()
            if !sticker { eyes(ctx, p) }
            beak(ctx, p)
            arcs(ctx, p)
            if !p.dots.isEmpty && !sticker { dots(ctx, p) }
        }

        /// One wing's loop (side 1 = left, as chick.swift), raised by `flap` about its root inside the body.
        func wingLoop(_ side: CGFloat, flap: CGFloat) -> CGPath {
            let wg = g.wing
            let centre = CGPoint(x: g.cx + side * wg.dx, y: wg.cy)
            var t = CGAffineTransform(translationX: centre.x, y: centre.y).rotated(by: side * wg.deg * .pi / 180)
            // the root: the end of the long axis nearer the body's middle
            let ends = [CGPoint(x: wg.rx, y: 0), CGPoint(x: -wg.rx, y: 0)].map { $0.applying(t) }
            let root = abs(ends[0].x - g.cx) < abs(ends[1].x - g.cx) ? ends[0] : ends[1]
            // up = the outer end rises: clockwise on screen (y down) for the left wing, anticlockwise for the right
            t = t.concatenating(CGAffineTransform(translationX: -root.x, y: -root.y))
                .concatenating(CGAffineTransform(rotationAngle: side * flap))
                .concatenating(CGAffineTransform(translationX: root.x, y: root.y))
            return CGPath(ellipseIn: CGRect(x: -wg.rx, y: -wg.ry, width: 2 * wg.rx, height: 2 * wg.ry), transform: &t)
        }

        func eyes(_ ctx: CGContext, _ p: MascotPose) {
            let e = g.eye
            for s: CGFloat in [-1, 1] {
                let c = CGPoint(x: g.cx + s * e.dx + p.look.x * e.r * 0.5, y: e.cy + p.look.y * e.r * 0.5)
                if p.happy {
                    // ^ ^: a smiling arc where the eye was
                    let a = CGMutablePath()
                    a.move(to: CGPoint(x: c.x - e.r * 0.95, y: c.y + e.r * 0.35))
                    a.addQuadCurve(to: CGPoint(x: c.x + e.r * 0.95, y: c.y + e.r * 0.35), control: CGPoint(x: c.x, y: c.y - e.r * 1.25))
                    ctx.addPath(a); ctx.setLineWidth(min(e.r * 0.7, width * 0.9)); ctx.setStrokeColor(lineColor); ctx.strokePath()
                    continue
                }
                let h = max(0.1, 1 - p.blink)
                ctx.setFillColor(lineColor)
                ctx.fillEllipse(in: CGRect(x: c.x - e.r, y: c.y - e.r * h, width: 2 * e.r, height: 2 * e.r * h))
                if g.glint.r > 0 && h > 0.6 {
                    ctx.setFillColor(color(MascotPalette.glint))
                    let r = g.glint.r
                    ctx.fillEllipse(in: CGRect(x: c.x + g.glint.dx - r, y: c.y + g.glint.dy * h - r, width: 2 * r, height: 2 * r))
                }
            }
            ctx.setLineWidth(width)
        }

        /// The diamond beak; open = the lower half drops (a dark mouth between).
        func beak(_ ctx: CGContext, _ p: MascotPose) {
            let b = g.beak
            let top = CGPoint(x: g.cx, y: b.cy - b.up), l = CGPoint(x: g.cx - b.w, y: b.cy), r = CGPoint(x: g.cx + b.w, y: b.cy)
            let bottom = CGPoint(x: g.cx, y: b.cy + b.down)
            let open = p.beak * b.down * 0.45
            // a lighter line round the beak, so the coral shows (small: lighter still, or the face turns into one blot)
            ctx.setLineWidth(sticker ? width : width * (g.filledBeak ? 0.45 : 0.62))
            ctx.setStrokeColor(lineColor)
            if open > 1 && !sticker {
                let mouth = CGMutablePath()
                mouth.addLines(between: [l, r, CGPoint(x: r.x - b.w * 0.12, y: r.y + open), CGPoint(x: l.x + b.w * 0.12, y: l.y + open)])
                mouth.closeSubpath()
                ctx.addPath(mouth); ctx.setFillColor(lineColor); ctx.fillPath()
            }
            let upper = CGMutablePath(), lower = CGMutablePath()
            upper.addLines(between: [l, top, r]); upper.closeSubpath()
            lower.addLines(between: [l, r, bottom].map { CGPoint(x: $0.x, y: $0.y + open) }); lower.closeSubpath()
            for half in [upper, lower] {
                ctx.addPath(half); ctx.setFillColor(color(MascotPalette.beak)); ctx.fillPath()
            }
            if open > 1 || sticker {
                for half in [upper, lower] { ctx.addPath(half); ctx.strokePath() }
            } else {
                let d = CGMutablePath()
                d.addLines(between: [top, r, bottom, l]); d.closeSubpath()
                ctx.addPath(d); ctx.strokePath()
                if g.slit { ctx.move(to: l); ctx.addLine(to: r); ctx.strokePath() }
            }
        }

        func arcs(_ ctx: CGContext, _ p: MascotPose) {
            if rimOnly { return }
            ctx.setLineWidth(width)
            for (i, a) in g.arcs.enumerated() {
                let alpha = i < p.arcs.count ? p.arcs[i] : 1
                guard alpha > 0.01 else { continue }
                let grow = i < p.arcGrow.count ? p.arcGrow[i] : 0
                ctx.addArc(center: g.arcCentre, radius: a.r * (1 + grow), startAngle: a.from * .pi / 180, endAngle: a.to * .pi / 180,
                           clockwise: false)
                ctx.setStrokeColor(sticker ? color(0xFFFFFF) : free(alpha))
                ctx.strokePath()
            }
        }

        /// Thought dots rising to the upper right, where the arcs were.
        func dots(_ ctx: CGContext, _ p: MascotPose) {
            let at: [(CGFloat, CGFloat, CGFloat)] = [(900, 380, 30), (990, 255, 40), (1095, 115, 52)]
            for (i, a) in p.dots.enumerated() where i < at.count && a > 0.01 {
                let (x, y, r) = at[i]
                let rr = r * (0.6 + 0.4 * a)
                ctx.setFillColor(free(a))
                ctx.fillEllipse(in: CGRect(x: x - rr, y: y - rr - 14 * a, width: 2 * rr, height: 2 * rr))
            }
        }

        // MARK: the egg

        func egg(_ ctx: CGContext, _ p: MascotPose) {
            let e = MascotArt.egg
            ctx.saveGState()
            // rocks about its bottom
            let pivot = CGPoint(x: g.cx, y: e.bottom)
            ctx.translateBy(x: pivot.x, y: pivot.y + p.cupDrop)
            ctx.rotate(by: p.eggTilt)
            ctx.translateBy(x: -pivot.x, y: -pivot.y)
            ctx.setLineWidth(width)
            ctx.setStrokeColor(lineColor)
            if p.egg {
                ctx.addPath(e.whole); ctx.setFillColor(color(MascotPalette.shell)); ctx.fillPath()
                if !sticker { eggShine(ctx) }
                ctx.addPath(e.whole); ctx.strokePath()
                if p.crack > 0 && !sticker {
                    ctx.saveGState()
                    ctx.addPath(e.whole); ctx.clip()
                    let n = e.crack.count - 1
                    let upto = p.crack * CGFloat(n)
                    ctx.move(to: e.crack[0])
                    for i in 1...n {
                        let f = min(1, max(0, upto - CGFloat(i - 1)))
                        guard f > 0 else { break }
                        let a = e.crack[i - 1], b = e.crack[i]
                        ctx.addLine(to: CGPoint(x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f))
                    }
                    ctx.strokePath()
                    ctx.restoreGState()
                }
            } else if p.cup > 0 {
                // solid all the way: it shrinks about its bottom (a fade showed a grey ghost of the shell)
                ctx.translateBy(x: pivot.x, y: pivot.y)
                ctx.scaleBy(x: 0.4 + 0.6 * p.cup, y: p.cup)
                ctx.translateBy(x: -pivot.x, y: -pivot.y)
                ctx.addPath(e.cup); ctx.setFillColor(color(MascotPalette.shell)); ctx.fillPath()
                ctx.addPath(e.cup); ctx.strokePath()
            }
            ctx.restoreGState()
            if !p.egg && p.cap.alpha > 0 {
                ctx.saveGState()
                let c = CGPoint(x: g.cx, y: e.crackY - 200)
                ctx.translateBy(x: c.x + p.cap.dx, y: c.y + p.cap.dy)
                ctx.rotate(by: p.cap.turn)
                ctx.scaleBy(x: p.cap.size, y: p.cap.size)
                ctx.translateBy(x: -c.x, y: -c.y)
                ctx.addPath(e.cap); ctx.setFillColor(color(MascotPalette.shell)); ctx.fillPath()
                ctx.addPath(e.cap); ctx.setLineWidth(width); ctx.setStrokeColor(lineColor); ctx.strokePath()
                ctx.restoreGState()
            }
        }

        /// A short highlight on the shell, upper left.
        func eggShine(_ ctx: CGContext) {
            let e = MascotArt.egg
            ctx.saveGState()
            ctx.setLineWidth(width * 0.8)
            ctx.setStrokeColor(color(0xFFFFFF, 0.9))
            ctx.addArc(center: CGPoint(x: g.cx, y: e.bottom - e.height * 0.52), radius: e.width * 0.36,
                       startAngle: .pi * 1.13, endAngle: .pi * 1.3, clockwise: false)
            ctx.strokePath()
            ctx.restoreGState()
        }

        // MARK: sparkles, the bug

        /// A plump four-point star, warm yellow or coral, no line (a lined one reads as a cross at small sizes).
        func sparkle(_ ctx: CGContext, _ c: CGPoint, _ r: CGFloat, _ a: CGFloat, warm: Bool) {
            guard r > 1 else { return }
            let s = CGMutablePath()
            let pts = [CGPoint(x: 0, y: -r), CGPoint(x: r, y: 0), CGPoint(x: 0, y: r), CGPoint(x: -r, y: 0)]
            s.move(to: CGPoint(x: c.x + pts[0].x, y: c.y + pts[0].y))
            for i in 1...4 {
                let p = pts[i % 4], q = pts[i - 1]
                // the waist between two points, a little out from the centre
                let w = CGPoint(x: c.x + (p.x + q.x) * 0.16, y: c.y + (p.y + q.y) * 0.16)
                s.addQuadCurve(to: CGPoint(x: c.x + p.x, y: c.y + p.y), control: w)
            }
            s.closeSubpath()
            ctx.addPath(s)
            ctx.setFillColor(color(warm ? MascotPalette.wing : MascotPalette.beak, a))
            ctx.fillPath()
        }

        func bug(_ ctx: CGContext, _ p: MascotPose) {
            let s: CGFloat = 230
            let r = CGRect(x: bugAt.x - s / 2 * (1 + p.bugSquish), y: bugAt.y + 70 - s * (1 - p.bugSquish),
                           width: s * (1 + p.bugSquish), height: s * (1 - p.bugSquish))
            ctx.saveGState()
            ctx.setAlpha(p.bug)
            mascotDrawBug(ctx, r, dark: style.dark)
            ctx.restoreGState()
        }
    }

    // MARK: - the egg's shape

    struct Egg {
        let width: CGFloat, height: CGFloat, bottom: CGFloat, crackY: CGFloat
        let whole: CGPath, cup: CGPath, cap: CGPath
        /// where a chick in the cup may show: inside the shell or above the crack
        let room: CGPath
        let crack: [CGPoint]
    }

    /// The egg the chick hatches from: as wide as the body, a little taller, its foot on the chick's; the crack a zigzag
    /// just above its widest point. Cup and cap are the egg cut along the crack.
    static let egg: Egg = {
        let g = MascotGeometry.master
        let w: CGFloat = 860, h: CGFloat = 1000, bottom = g.foot + 8, cx = g.cx
        let waist = bottom - h * 0.42                  // the widest line: below it a rounder half, above a taller one
        let k: CGFloat = 0.5523
        let p = CGMutablePath()
        p.move(to: CGPoint(x: cx, y: bottom))
        p.addCurve(to: CGPoint(x: cx + w / 2, y: waist), control1: CGPoint(x: cx + k * w / 2, y: bottom),
                   control2: CGPoint(x: cx + w / 2, y: waist + k * (bottom - waist)))
        p.addCurve(to: CGPoint(x: cx, y: bottom - h), control1: CGPoint(x: cx + w / 2, y: waist - 0.62 * (waist - (bottom - h))),
                   control2: CGPoint(x: cx + 0.6 * w / 2, y: bottom - h))
        p.addCurve(to: CGPoint(x: cx - w / 2, y: waist), control1: CGPoint(x: cx - 0.6 * w / 2, y: bottom - h),
                   control2: CGPoint(x: cx - w / 2, y: waist - 0.62 * (waist - (bottom - h))))
        p.addCurve(to: CGPoint(x: cx, y: bottom), control1: CGPoint(x: cx - w / 2, y: waist + k * (bottom - waist)),
                   control2: CGPoint(x: cx - k * w / 2, y: bottom))
        p.closeSubpath()
        let cy = waist - 50
        let teeth = 7
        var zig: [CGPoint] = []
        for i in 0...teeth * 2 {
            let x = cx - w / 2 - 20 + (w + 40) * CGFloat(i) / CGFloat(teeth * 2)
            zig.append(CGPoint(x: x, y: cy + (i % 2 == 0 ? 34 : -34)))
        }
        let below = CGMutablePath(), above = CGMutablePath()
        below.addLines(between: zig + [CGPoint(x: cx + w, y: bottom + 50), CGPoint(x: cx - w, y: bottom + 50)]); below.closeSubpath()
        above.addLines(between: zig + [CGPoint(x: cx + w, y: bottom - h - 50), CGPoint(x: cx - w, y: bottom - h - 50)]); above.closeSubpath()
        let sky = CGPath(rect: CGRect(x: stage.minX, y: stage.minY, width: stage.width, height: cy - stage.minY), transform: nil)
        return Egg(width: w, height: h, bottom: bottom, crackY: cy, whole: p, cup: p.intersection(below), cap: p.intersection(above),
                   room: p.union(sky), crack: zig)
    }()
}
